# -*- coding: utf-8 -*-
SVGS = ['<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="26" text-anchor="middle" font-size="14.5" font-weight="bold" fill="#0f172a">THEME 3: PERSONAL LIFE &amp; WELL-BEING — VOCABULARY</text>\n  <rect x="22" y="42" width="320" height="175" rx="10" fill="#eff6ff" stroke="#2563eb" stroke-width="2"/>\n  <text x="182" y="64" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#1e40af">HEALTHY LIFESTYLE &amp; NUTRITION</text>\n  <text x="35" y="88" font-size="11.2" fill="#1e3a8a">• Balanced diet : Dengeli beslenme</text>\n  <text x="35" y="110" font-size="11.2" fill="#1e3a8a">• Nutritious / Nutrient : Besleyici / Besin öğesi</text>\n  <text x="35" y="132" font-size="11.2" fill="#1e3a8a">• Cut down on junk food : Abur cuburu azaltmak</text>\n  <text x="35" y="154" font-size="11.2" fill="#1e3a8a">• Stay hydrated : Yeterli su içmek / Susuz kalmamak</text>\n  <text x="35" y="176" font-size="11.2" fill="#1e3a8a">• Sedentary lifestyle : Hareketsiz yaşam tarzı</text>\n  <rect x="358" y="42" width="320" height="175" rx="10" fill="#f0fdf4" stroke="#16a34a" stroke-width="2"/>\n  <text x="518" y="64" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#166534">SPORTS &amp; MENTAL WELL-BEING</text>\n  <text x="370" y="88" font-size="11.2" fill="#14532d">• Work out / Physical activity : Egzersiz yapmak</text>\n  <text x="370" y="110" font-size="11.2" fill="#14532d">• Keep fit / Stamina : Formda kalmak / Dayanıklılık</text>\n  <text x="370" y="132" font-size="11.2" fill="#14532d">• Cope with stress : Stresle başa çıkmak</text>\n  <text x="370" y="154" font-size="11.2" fill="#14532d">• Mindfulness &amp; Resilience : Bilinçli farkındalık ve direnç</text>\n  <text x="370" y="176" font-size="11.2" fill="#14532d">• Quality sleep pattern : Kaliteli uyku düzeni</text>\n  <rect x="22" y="224" width="656" height="26" rx="6" fill="#e2e8f0"/>\n  <text x="350" y="241" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#1e293b">Well-being encompasses both physical health (nutrition &amp; exercise) and emotional balance.</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="26" text-anchor="middle" font-size="14.5" font-weight="bold" fill="#0f172a">MODAL VERBS FOR ADVICE, STRONG WARNING &amp; NECESSITY</text>\n  <rect x="22" y="42" width="320" height="175" rx="10" fill="#fefce8" stroke="#ca8a04" stroke-width="2"/>\n  <text x="182" y="64" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#854d0e">GIVING ADVICE (SHOULD / OUGHT TO / HAD BETTER)</text>\n  <text x="35" y="88" font-size="11" fill="#713f12">• should / ought to + V1 : Genel tavsiye ve öğüt</text>\n  <text x="35" y="106" font-size="11" fill="#713f12">  «You should eat fresh vegetables and fruits.»</text>\n  <text x="35" y="128" font-size="11" fill="#713f12">• shouldn\'t / ought not to + V1 : Olumsuz tavsiye</text>\n  <text x="35" y="148" font-size="11" fill="#713f12">• had better (not) + V1 : Güçlü tavsiye / Uyarı (Aksi</text>\n  <text x="35" y="166" font-size="11" fill="#713f12">  hâlde olumsuz bir sonuç doğacağını bildirir):</text>\n  <text x="35" y="184" font-size="11" font-weight="bold" fill="#854d0e">  «You had better see a doctor before it gets worse.»</text>\n  <rect x="358" y="42" width="320" height="175" rx="10" fill="#faf5ff" stroke="#9333ea" stroke-width="2"/>\n  <text x="518" y="64" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#6b21a8">OBLIGATION &amp; LACK OF NECESSITY</text>\n  <text x="370" y="88" font-size="11" fill="#581c87">• must / have to + V1 : Zorunluluk ve gereklilik</text>\n  <text x="370" y="108" font-size="11" fill="#581c87">  «Athletes must follow a strict training schedule.»</text>\n  <text x="370" y="130" font-size="11" fill="#581c87">• mustn\'t + V1 : Yasaklama (Prohibition)</text>\n  <text x="370" y="150" font-size="11" fill="#581c87">• don\'t have to / needn\'t + V1 : Zorunluluk yok</text>\n  <text x="370" y="168" font-size="11" fill="#581c87">  (Gerek yok, isteğe bağlı):</text>\n  <text x="370" y="184" font-size="11" font-weight="bold" fill="#6b21a8">  «You don\'t have to buy expensive gym equipment.»</text>\n  <rect x="22" y="224" width="656" height="26" rx="6" fill="#e2e8f0"/>\n  <text x="350" y="241" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#1e293b">Dikkat: \'had better\' yapısında \'to\' kullanılmaz → You\'d better sleep early / You\'d better not skip breakfast.</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="26" text-anchor="middle" font-size="14.5" font-weight="bold" fill="#0f172a">EXPRESSING PAST &amp; PRESENT HABITS AND QUANTIFIERS IN NUTRITION</text>\n  <rect x="22" y="42" width="320" height="175" rx="10" fill="#fff7ed" stroke="#ea580c" stroke-width="2"/>\n  <text x="182" y="64" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#9a3412">PAST VS. PRESENT HABITS (USED TO)</text>\n  <text x="35" y="88" font-size="11" fill="#7c2d12">• used to + V1 : Geçmişte yapılan ama artık bırakılan</text>\n  <text x="35" y="106" font-size="11" fill="#7c2d12">  alışkanlıklar («I used to eat fast food, but now I don\'t.»)</text>\n  <text x="35" y="128" font-size="11" fill="#7c2d12">• didn\'t use to + V1 / Did you use to + V1?</text>\n  <text x="35" y="150" font-size="11" fill="#7c2d12">• be used to + V-ing / Noun : Bir şeye alışkın olmak</text>\n  <text x="35" y="168" font-size="11" fill="#7c2d12">  «She is used to waking up early for morning runs.»</text>\n  <text x="35" y="186" font-size="11" fill="#7c2d12">• get used to + V-ing / Noun : Alışmaya başlamak</text>\n  <rect x="358" y="42" width="320" height="175" rx="10" fill="#ecfeff" stroke="#0891b2" stroke-width="2"/>\n  <text x="518" y="64" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#155e75">QUANTIFIERS &amp; RESULT CLAUSES FOR HEALTH</text>\n  <text x="370" y="88" font-size="11" fill="#164e63">• too much + Uncountable : too much sugar / salt / stress</text>\n  <text x="370" y="110" font-size="11" fill="#164e63">• too many + Plural Countable : too many calories / snacks</text>\n  <text x="370" y="132" font-size="11" fill="#164e63">• enough + Noun : enough water / enough sleep</text>\n  <text x="370" y="154" font-size="11" fill="#164e63">• Adjective + enough : active enough / strong enough</text>\n  <text x="370" y="176" font-size="11" font-weight="bold" fill="#155e75">•plenty of / a balanced amount of vitamins &amp; fiber</text>\n  <rect x="22" y="224" width="656" height="26" rx="6" fill="#e2e8f0"/>\n  <text x="350" y="241" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#1e293b">\'used to + V1\' geçmiş alışkanlığı, \'be/get used to + V-ing\' ise mevcut alışkın olma durumunu anlatır.</text>\n</svg>']

def uygula(v):
    for i, b in enumerate(v.get("bolumler", [])):
        if i < len(SVGS):
            b["gorsel"] = SVGS[i]
